<?php

declare(strict_types=1);

namespace App\Play\Domain\Campaign\Lists;

/**
 * The campaign already holds an NPC with this id. Ids are generated by the caller, so a repeated
 * command must not replace the existing NPC.
 */
final class NpcAlreadyExists extends \DomainException
{
    public static function withId(NpcId $id): self
    {
        return new self(\sprintf('NPC "%s" already exists.', $id->toString()));
    }
}
